        for i, x in enumerate(arr):
            pos = bisect_left(lis, x)
            if pos < len(lis):
                lis[pos] = x
            else:
                lis.append(x)
            lis_index[pos] = i
            if pos > 0:
                parent[i] = lis_index[pos - 1]
        return lis, parent, lis_index

    def longest_decreasing_subsequence(arr):
