    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    # Function to find the longest increasing subsequence (LIS)
    def lis(sequence):
        if not sequence:
            return []
        lis = [1] * len(sequence)
        prev = [-1] * len(sequence)
        for i in range(1, len(sequence)):
            for j in range(i):
                if sequence[i] > sequence[j] and lis[i] < lis[j] + 1:
                    lis[i] = lis[j] + 1
                    prev[i] = j
        # Reconstruct the LIS
        max_len = max(lis)
        index = lis.index(max_len)
        result = []
        while index != -1:
            result.append(sequence[index])
            index = prev[index]
        return result[::-1]

    # Function to find the longest decreasing subsequence (LDS)
    def lds(sequence):
        if not sequence:
            return []
        lds = [1] * len(sequence)
        prev = [-1] * len(sequence)
        for i in range(1, len(sequence)):
            for j in range(i):
                if sequence[i] < sequence[j] and lds[i] < lds[j] + 1:
                    lds[i] = lds[j] + 1
                    prev[i] = j
        # Reconstruct the LDS
        max_len = max(lds)
        index = lds.index(max_len)
        result = []
        while index != -1:
            result.append(sequence[index])
            index = prev[index]
        return result[::-1]

